import { z } from 'zod'

export const runtimeStatusValues = [
  'available_and_ready',
  'available_but_may_require_approval',
  'unavailable',
  'optional_but_missing',
] as const

export type RuntimeStatus = typeof runtimeStatusValues[number]

export const sourceTypeValues = ['github_issue', 'repo_signal'] as const
export type SourceType = typeof sourceTypeValues[number]

export const laneValues = ['docs', 'tests', 'simple_bugs', 'experimental'] as const
export type Lane = typeof laneValues[number]

export const riskZoneValues = ['low', 'medium', 'high'] as const
export type RiskZone = typeof riskZoneValues[number]

export const taskStateValues = [
  'discovered',
  'qualified',
  'workspace_prepared',
  'implementing',
  'validating',
  'draft_pr_open',
  'review_in_progress',
  'changes_requested',
  'review_complete',
  'ready_pr',
  'human_required',
  'awaiting_portal_submission',
  'portal_submitted',
  'judge_pending',
  'judge_approved',
  'judge_adjusted',
  'judge_rejected',
  'blocked',
  'duplicate_closed',
  'abandoned',
] as const

export type TaskState = typeof taskStateValues[number]

export const terminalTaskStates = new Set<TaskState>([
  'judge_approved',
  'judge_adjusted',
  'judge_rejected',
  'duplicate_closed',
  'abandoned',
])

export const activeTaskStates = new Set<TaskState>(taskStateValues.filter((state) => !terminalTaskStates.has(state)))

export const duplicateRiskValues = ['none', 'hard_duplicate', 'likely_duplicate', 'split_risk'] as const
export type DuplicateRiskClass = typeof duplicateRiskValues[number]

export const portalStatusValues = ['not_started', 'awaiting_submission', 'submitted'] as const
export type PortalStatus = typeof portalStatusValues[number]

export const judgeStatusValues = ['not_started', 'pending', 'approved', 'adjusted', 'rejected'] as const
export type JudgeStatus = typeof judgeStatusValues[number]

export const autonomyClassValues = ['fully_autonomous', 'approval_sensitive', 'optional'] as const
export type AutonomyClass = typeof autonomyClassValues[number]

export const validationParserValues = ['exit_code', 'line_set', 'integration_spec_coverage'] as const
export type ValidationParser = typeof validationParserValues[number]

export const cwdModeValues = ['repo_root', 'target_root', 'worktree'] as const
export type CwdMode = typeof cwdModeValues[number]

export const blockerReasonValues = [
  'permission_blocked',
  'github_provider_unavailable',
  'validation_failed',
  'duplicate_risk_high',
  'review_unresolved',
  'policy_exception_required',
  'tool_missing',
  'target_repo_unavailable',
  'timeout_exceeded',
] as const

export type BlockerReason = typeof blockerReasonValues[number]

export const runRoleValues = ['implementer', 'reviewer'] as const
export type RunRole = typeof runRoleValues[number]

export const runtimeStatusSchema = z.enum(runtimeStatusValues)
export const sourceTypeSchema = z.enum(sourceTypeValues)
export const laneSchema = z.enum(laneValues)
export const riskZoneSchema = z.enum(riskZoneValues)
export const taskStateSchema = z.enum(taskStateValues)
export const duplicateRiskSchema = z.enum(duplicateRiskValues)
export const portalStatusSchema = z.enum(portalStatusValues)
export const judgeStatusSchema = z.enum(judgeStatusValues)
export const autonomyClassSchema = z.enum(autonomyClassValues)
export const validationParserSchema = z.enum(validationParserValues)
export const cwdModeSchema = z.enum(cwdModeValues)
export const blockerReasonSchema = z.enum(blockerReasonValues)
export const runRoleSchema = z.enum(runRoleValues)
